// 1. Get the raw input
const input = $input.first().json;
let parsed;

try {
  // Get raw text from potential agent output locations
  // We check input.text, input.output, etc. to handle different agent return types
  let raw = input.text || input.output || input.response || (input.message && input.message.content) || JSON.stringify(input);

  // --- ROBUST JSON EXTRACTION ---
  // Agents sometimes add conversational fluff ("Here is the JSON...").
  // We extract everything between the first '{' and last '}' to isolate the object.
  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1) {
    raw = raw.substring(firstBrace, lastBrace + 1);
  }

  // Parse the cleaned string
  parsed = JSON.parse(raw);

} catch (e) {
  throw new Error(`Failed to parse Script Agent JSON. Raw output was not valid JSON. Error: ${e.message}`);
}

// 2. Validate essential fields
if (!parsed.video_script) {
  throw new Error("Missing 'video_script' field in Agent output.");
}

// --- CLEANING FOR AUDIO (TTS) ---
// Create a clean version specifically for the voiceover engine.
let cleanText = parsed.video_script;

// A. Specific TTS Improvements (Handle BEFORE general deletion)
// Convert pause instructions like (long pause) to ellipses for natural TTS timing
cleanText = cleanText.replace(/\(pause.*?\)/gi, '...'); 
cleanText = cleanText.replace(/\[pause.*?\]/gi, '...');

// B. Remove Visual Cues in [brackets] and (parentheses)
// This strips out [Visual: Man walking] or (Camera zooms in)
cleanText = cleanText.replace(/\[.*?\]/g, ''); 
cleanText = cleanText.replace(/\(.*?\)/g, ''); 

// C. Remove Markdown formatting
cleanText = cleanText.replace(/\*\*(.*?)\*\*/g, '$1'); // Bold (**text**)
cleanText = cleanText.replace(/\*(.*?)\*/g, '$1');      // Italics (*text*)
cleanText = cleanText.replace(/__(.*?)__/g, '$1');      // Bold (__text__)
cleanText = cleanText.replace(/_(.*?)_/g, '$1');        // Italics (_text_)

// D. Remove "Rationale" footer if present (prevents voice reading metadata)
const rationaleIndex = cleanText.toLowerCase().indexOf('rationale:');
if (rationaleIndex !== -1) {
    cleanText = cleanText.substring(0, rationaleIndex);
}

// E. Normalize whitespace (remove double spaces left by deletions)
cleanText = cleanText.replace(/\s+/g, ' ').trim();


// 3. Return the Data
return {
  json: {
    // The Human-Readable Script (Keep formatting/visuals for the video editor/human review)
    video_script: parsed.video_script,

    // The Robot-Readable Script (Clean for ElevenLabs) -> consistent naming with Workflow 2
    voiceover_text: cleanText,

    hook_rationale: parsed.hook_rationale || "No rationale provided",

    // Pass through context (IDs, keywords, etc.) from previous steps
    ...$('Loop â€” Item Processor').item.json,

    // Pass through research source for debugging/logging
    research_source: $('Code â€” Parse Research').item.json.formatted_source_map
  }
};

