// 1. Get the raw data from the Perplexity (Agent â€” Researcher) node
// We use $input.first() because n8n processes items in batches
const rawData = $input.first().json;

// Safe extraction of content and citations (handles cases where Perplexity finds 0 sources)
const rawContent = rawData.choices && rawData.choices[0] && rawData.choices[0].message ? rawData.choices[0].message.content : "No research content found.";
const citations = rawData.citations || [];

// 2. Initialize our output variables
let sourceMap = "### BIBLIOGRAPHY & SOURCE MAP\n";
let richContent = rawContent;

// 3. Loop through citations to build the Map and enhance the Notes
citations.forEach((url, index) => {
  const citationNumber = index + 1;
  let domain = "External Source";

  // Try to extract a clean domain name (e.g., "bloomberg.com")
  try {
    const urlObj = new URL(url);
    domain = urlObj.hostname.replace('www.', '');
  } catch (e) {
    // If URL is malformed, keep default
  }

  // A. Build the Source Map
  // Format: [1]: https://url.com (Source: bloomberg.com)
  sourceMap += `[${citationNumber}]: ${url} (Source: ${domain})\n`;

  // B. Enhance the Research Notes (Optional but recommended)
  // This helps the AI attribute the source *inline* without constantly cross-referencing.
  // Changes "...inflation is up [1]." to "...inflation is up [1] (bloomberg.com)."

  // Regex explains: Find [1] but NOT [10], [11] etc.
  const markerRegex = new RegExp(`\\[${citationNumber}\\](?!\\d)`, 'g');
  richContent = richContent.replace(markerRegex, `[${citationNumber}] (${domain})`);
});

// 4. Return the data structure exactly as the Prompt expects it
return {
  json: {
    // Pass through original data just in case
    ...rawData,

    // The specific fields requested in the Prompt
    formatted_source_map: sourceMap,
    rich_research_notes: richContent,

    // Helper: Total number of sources found
    source_count: citations.length
  }
};

